class DigiStore{constructor(){this.dbName="digicom_offline_db",this.dbVersion=1,this.db=null}async init(){return this.db?this.db:new Promise((resolve,reject)=>{const request=indexedDB.open(this.dbName,this.dbVersion);request.onupgradeneeded=event=>{const db=event.target.result;if(db.objectStoreNames.contains("contacts")||db.createObjectStore("contacts",{keyPath:"id"}),!db.objectStoreNames.contains("messages")){const msgStore=db.createObjectStore("messages",{keyPath:"id"});msgStore.createIndex("senderId","senderId",{unique:!1}),msgStore.createIndex("receiverId","receiverId",{unique:!1}),msgStore.createIndex("timestamp","timestamp",{unique:!1})}db.objectStoreNames.contains("outbox")||db.createObjectStore("outbox",{keyPath:"id"})},request.onsuccess=event=>{this.db=event.target.result,console.log("[+] DigiStore IndexedDB initialized successfully."),resolve(this.db)},request.onerror=event=>{console.error("[-] DigiStore IndexedDB error:",event.target.error),reject(event.target.error)}})}async saveContacts(contactsList){return this.db||await this.init(),new Promise((resolve,reject)=>{const tx=this.db.transaction("contacts","readwrite"),store=tx.objectStore("contacts");contactsList.forEach(contact=>{store.put(contact)}),tx.oncomplete=()=>resolve(!0),tx.onerror=e=>reject(e.target.error)})}async getContacts(){return this.db||await this.init(),new Promise((resolve,reject)=>{const request=this.db.transaction("contacts","readonly").objectStore("contacts").getAll();request.onsuccess=()=>resolve(request.result||[]),request.onerror=e=>reject(e.target.error)})}async saveMessage(msg){return this.db||await this.init(),new Promise((resolve,reject)=>{const tx=this.db.transaction("messages","readwrite");tx.objectStore("messages").put(msg),tx.oncomplete=()=>resolve(!0),tx.onerror=e=>reject(e.target.error)})}async saveMessagesBatch(messages){return this.db||await this.init(),new Promise((resolve,reject)=>{const tx=this.db.transaction("messages","readwrite"),store=tx.objectStore("messages");messages.forEach(msg=>store.put(msg)),tx.oncomplete=()=>resolve(!0),tx.onerror=e=>reject(e.target.error)})}async getMessage(id){return this.db||await this.init(),new Promise((resolve,reject)=>{const request=this.db.transaction("messages","readonly").objectStore("messages").get(id);request.onsuccess=()=>resolve(request.result||null),request.onerror=e=>reject(e.target.error)})}async updateMessageContent(id,newContent,isEdited=1,editedAt=null){return this.db||await this.init(),new Promise((resolve,reject)=>{const tx=this.db.transaction("messages","readwrite"),store=tx.objectStore("messages"),request=store.get(id);request.onsuccess=()=>{const msg=request.result;msg&&("object"==typeof msg.content&&null!==msg.content?msg.content.text=newContent:msg.content={type:"text",text:newContent},msg.is_edited=isEdited,msg.isEdited=isEdited,editedAt&&(msg.edited_at=editedAt),store.put(msg)),resolve(!0)},request.onerror=e=>reject(e.target.error),tx.onerror=e=>reject(e.target.error)})}async deleteMessage(id){return this.db||await this.init(),new Promise((resolve,reject)=>{const tx=this.db.transaction("messages","readwrite");tx.objectStore("messages").delete(id),tx.oncomplete=()=>resolve(!0),tx.onerror=e=>reject(e.target.error)})}async getMessages(currentUserId,targetUserId,limit=50,beforeTimestamp=null){return this.db||await this.init(),new Promise((resolve,reject)=>{const index=this.db.transaction("messages","readonly").objectStore("messages").index("timestamp"),cId=String(currentUserId),tId=String(targetUserId);let keyRange=null;beforeTimestamp&&(keyRange=IDBKeyRange.upperBound(beforeTimestamp,!0));const results=[],cursorRequest=index.openCursor(keyRange,"prev");cursorRequest.onsuccess=event=>{const cursor=event.target.result;if(cursor&&results.length<limit){const m=cursor.value,sId=String(m.senderId||m.sender_id||""),rId=String(m.receiverId||m.receiver_id||"");(sId===cId&&rId===tId||sId===tId&&rId===cId)&&results.push(m),cursor.continue()}else results.sort((a,b)=>new Date(a.timestamp)-new Date(b.timestamp)),resolve(results)},cursorRequest.onerror=e=>reject(e.target.error)})}async addToOutbox(msgPayload){return this.db||await this.init(),new Promise((resolve,reject)=>{const tx=this.db.transaction("outbox","readwrite");tx.objectStore("outbox").put(msgPayload),tx.oncomplete=()=>resolve(!0),tx.onerror=e=>reject(e.target.error)})}async getOutbox(){return this.db||await this.init(),new Promise((resolve,reject)=>{const request=this.db.transaction("outbox","readonly").objectStore("outbox").getAll();request.onsuccess=()=>resolve(request.result||[]),request.onerror=e=>reject(e.target.error)})}async removeFromOutbox(id){return this.db||await this.init(),new Promise((resolve,reject)=>{const tx=this.db.transaction("outbox","readwrite");tx.objectStore("outbox").delete(id),tx.oncomplete=()=>resolve(!0),tx.onerror=e=>reject(e.target.error)})}async pruneOldMessages(maxPerConversation=500){this.db||await this.init();try{const store=this.db.transaction("messages","readwrite").objectStore("messages"),countReq=store.count();countReq.onsuccess=()=>{if(countReq.result>4*maxPerConversation){const index=store.index("timestamp");let deleted=0;const toDelete=countReq.result-2*maxPerConversation;index.openCursor().onsuccess=e=>{const cursor=e.target.result;cursor&&deleted<toDelete&&(cursor.delete(),deleted++,cursor.continue())}}}}catch(e){console.warn("[-] DigiStore prune warning:",e)}}async clearAllStores(){if(!this.db)try{await this.init()}catch(e){}return!!this.db&&new Promise(resolve=>{try{const tx=this.db.transaction(["contacts","messages","outbox"],"readwrite");tx.objectStore("contacts").clear(),tx.objectStore("messages").clear(),tx.objectStore("outbox").clear(),tx.oncomplete=()=>{console.log("[+] DigiStore cleared successfully on logout."),resolve(!0)},tx.onerror=()=>resolve(!1)}catch(e){console.warn("[-] Error clearing DigiStore:",e),resolve(!1)}})}}window.digiStore=new DigiStore;